package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.fail;

public class KeyedObjects2D_getObject_TriageGen1Test {

    private KeyedObjects2D keyedObjects2D;
    private final Comparable rowKey1 = "Row1";
    private final Comparable rowKey2 = "Row2";
    private final Comparable colKey1 = "Col1";
    private final Comparable colKey2 = "Col2";
    private final Object testValue = "TestData";

    @Before
    public void setUp() {
        keyedObjects2D = new KeyedObjects2D();
    }

    @Test
    public void testGetObject_NullRowKey_ThrowsIllegalArgumentException() {
        try {
            keyedObjects2D.getObject(null, colKey1);
            fail("Expected IllegalArgumentException for null rowKey");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'rowKey' argument.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_NullColumnKey_ThrowsIllegalArgumentException() {
        try {
            keyedObjects2D.getObject(rowKey1, null);
            fail("Expected IllegalArgumentException for null columnKey");
        } catch (IllegalArgumentException e) {
            assertEquals("Null 'columnKey' argument.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_UnknownRowKey_ThrowsUnknownKeyException() {
        // Setup with one valid key to ensure it's not a completely empty structure
        keyedObjects2D.addObject(testValue, rowKey1, colKey1);

        try {
            keyedObjects2D.getObject(rowKey2, colKey1);
            fail("Expected UnknownKeyException for unknown rowKey");
        } catch (UnknownKeyException e) {
            assertEquals("Row key (" + rowKey2 + ") not recognised.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_UnknownColumnKey_ThrowsUnknownKeyException() {
        // Setup row but use a column key not in the columnKeys list
        keyedObjects2D.addObject(testValue, rowKey1, colKey1);

        try {
            // Note: The logic 'if (column < 1)' in the source code implies 
            // that column index 0 is treated as unknown/invalid.
            // This test specifically targets the branch where column index is < 1.
            keyedObjects2D.getObject(rowKey1, rowKey2); 
            fail("Expected UnknownKeyException for unknown columnKey");
        } catch (UnknownKeyException e) {
            // The error message uses the columnKey passed in
            assertEquals("Column key (" + rowKey2 + ") not recognised.", e.getMessage());
        }
    }

    @Test
    public void testGetObject_ValidKeys_ReturnsValue() {
        // We need to bypass the 'column < 1' check. 
        // This means the columnKey must be at index 1 or higher in the columnKeys list.

        // Add first column (index 0)
        keyedObjects2D.addObject("dummy", rowKey1, "Col0");
        // Add second column (index 1)
        keyedObjects2D.addObject(testValue, rowKey1, colKey1);

        Object result = keyedObjects2D.getObject(rowKey1, colKey1);
        assertEquals(testValue, result);
    }

    @Test
    public void testGetObject_ValidKeys_ButValueMissing_ReturnsNull() {
        // Setup row and column so indexes are valid, but the specific cell is empty
        keyedObjects2D.addObject("dummy", rowKey1, "Col0");
        keyedObjects2D.addObject("dummy", rowKey1, colKey1);

        // Add a different column to ensure colKey2 exists in columnKeys but not in this row's data
        keyedObjects2D.addObject("dummy", rowKey1, colKey2);

        // We need colKey2 to be at index >= 1
        // Since we added Col0, Col1, Col2... Col2 is at index 2.

        Object result = keyedObjects2D.getObject(rowKey1, colKey2);
        assertNull(result);
    }

    @Test
    public void testGetObject_ColumnIndexZero_ThrowsUnknownKeyException() {
        // This specifically tests the 'if (column < 1)' branch
        // Even if the key exists, if it's at index 0, it throws UnknownKeyException
        keyedObjects2D.addObject(testValue, rowKey1, "FirstCol");

        try {
            keyedObjects2D.getObject(rowKey1, "FirstCol");
            fail("Expected UnknownKeyException because column index is 0");
        } catch (UnknownKeyException e) {
            assertEquals("Column key (FirstCol) not recognised.", e.getMessage());
        }
    }
}
